data class EtatDes(val valeur: Int? = null, val lancers: Int = 0)

class DesViewModel : ViewModel() {
    private val _etat = MutableStateFlow(EtatDes())
    val etat: StateFlow<EtatDes> = _etat.asStateFlow()

    fun lancer() {
        _etat.update { courant ->
            courant.copy(
                valeur = (1..6).random(),
                lancers = courant.lancers + 1,
            )
        }
    }
}

@Composable
fun EcranDes(viewModel: DesViewModel = viewModel()) {
    val etat by viewModel.etat.collectAsStateWithLifecycle()

    Column {
        Text("Résultat : ${etat.valeur ?: "-"}")
        Text("Lancers : ${etat.lancers}")
        Button(onClick = viewModel::lancer) {
            Text("Lancer le dé")
        }
    }
}

sealed interface EtatProfil {
    data object Chargement : EtatProfil
    data class Pret(val nom: String) : EtatProfil
    data class Echec(val message: String) : EtatProfil
}

fun texte(etat: EtatProfil) = when (etat) {
    EtatProfil.Chargement -> "Patientez..."
    is EtatProfil.Pret -> "Bienvenue, ${etat.nom}"
    is EtatProfil.Echec -> "Erreur : ${etat.message}"
}

fun main() {
    println(texte(EtatProfil.Chargement))
    println(texte(EtatProfil.Pret("Viviane")))
    println(texte(EtatProfil.Echec("réseau indisponible")))
}

