data class Inscription(val email: String, val age: String)

fun verifier(formulaire: Inscription): Map<String, String> {
    val erreurs = mutableMapOf<String, String>()

    if ('@' !in formulaire.email) {
        erreurs["email"] = "Adresse invalide"
    }
    val age = formulaire.age.toIntOrNull()
    if (age == null || age !in 13..120) {
        erreurs["age"] = "Âge invalide"
    }
    return erreurs
}

fun main() {
    println(verifier(Inscription("merlin@broceliande.fr", "42")))
    println(verifier(Inscription("merlin", "abc")))
}

data class EtatFormulaire(
    val email: String = "",
    val erreurEmail: String? = null,
    val envoiEnCours: Boolean = false,
)

class FormulaireViewModel : ViewModel() {
    private val _etat = MutableStateFlow(EtatFormulaire())
    val etat: StateFlow<EtatFormulaire> = _etat.asStateFlow()

    fun surEmail(valeur: String) {
        _etat.update { it.copy(email = valeur, erreurEmail = null) }
    }

    fun envoyer() {
        if ('@' !in _etat.value.email) {
            _etat.update { it.copy(erreurEmail = "Adresse invalide") }
        }
    }
}

